public static class Debug
{
    public static T Inspect<T>(T value,
        [CallerArgumentExpression(nameof(value))] string? expression = null)
    {
        Console.WriteLine($"[DEBUG] {expression} = {value}");
        return value;
    }
}

// Usage - can be inserted inline
